CREATE VIEW silver.patientIdentifierAnalystView 
AS 
EXECUTE AS User = 'analystUser'
SELECT top 1000
 patient_id,
    birthDate,
    deceasedDateTime,
    gender,
    maritalStatus_text,
    maritalStatus_coding_code,
    maritalStatus_coding_display,
    maritalStatus_coding_system,
    multipleBirthBoolean bit,
    multipleBirthInteger bigint,
    resourceType,
    text_div,
    text_status,
    identifier_system,
    identifier_type_coding_code,
    identifier_type_coding_system,
    identifier_type_text,
    case when identifier_type_text is null then null 
    when identifier_type_text in ('Driver''s License', 'Medical Record Number', 'Passport Number') then 'xxxx'
    when identifier_type_text = 'Social Security Number' then concat(substring(identifier_value, 1, 3), '-xx-xxxx')
    end as identifier_value ,
    name_family,
    name_given,
    name_prefix,
    name_suffix,
    name_use,
    telecom_system,
    telecom_use,
    telecom_value,
    communication_language_text,
    communication_language_coding_code,
    communication_language_coding_display,
    communication_language_coding_system
FROM  
fhir.patientIdentifier
WHERE
( IS_MEMBER('dataAnalyst') = 1 AND identifier_type_text in ('Driver''s License', 'Medical Record Number', 'Passport Number'))
